import React, { useEffect, useRef } from 'react';
import { Copy, Share2, Trash2, Edit2, Pin, Reply } from 'lucide-react';

interface MessageContextMenuProps {
  x: number;
  y: number;
  messageId: string;
  isMe: boolean;
  canDelete?: boolean;
  canManage?: boolean;
  isPinned?: boolean;
  content: string;
  onClose: () => void;
  onCopy: (content: string) => void;
  onShare: (messageId: string) => void;
  onDelete?: (messageId: string) => void;
  onEdit?: (messageId: string) => void;
  onReply?: (messageId: string) => void;
  onReact?: (messageId: string, emoji: string) => void;
  onPin?: (messageId: string) => void;
}

export const MessageContextMenu: React.FC<MessageContextMenuProps> = ({
  x, y, messageId, isMe, canDelete = isMe, canManage = false, isPinned = false,
  content, onClose, onCopy, onShare, onDelete, onEdit, onReply, onReact, onPin
}) => {
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onClose();
      }
    };
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscape);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscape);
    };
  }, [onClose]);

  // Ensure menu stays within viewport
  const style: React.CSSProperties = {
    position: 'fixed',
    top: y,
    left: x,
    zIndex: 1000,
  };

  // Adjust position if it goes off screen
  useEffect(() => {
    if (menuRef.current) {
      const rect = menuRef.current.getBoundingClientRect();
      const viewportWidth = window.innerWidth;
      const viewportHeight = window.innerHeight;

      if (rect.right > viewportWidth) {
        menuRef.current.style.left = `${viewportWidth - rect.width - 10}px`;
      }
      if (rect.bottom > viewportHeight) {
        menuRef.current.style.top = `${viewportHeight - rect.height - 10}px`;
      }
    }
  }, [x, y]);

  return (
    <div 
      ref={menuRef}
      style={style}
      role="menu"
      aria-label="Message actions"
      tabIndex={-1}
      className="bg-[#1A1A1A] border border-white/10 rounded-xl shadow-2xl py-2 min-w-[200px] overflow-hidden animate-in fade-in zoom-in duration-150"
      onContextMenu={(e) => e.preventDefault()}
    >
      {onReact && (
        <div className="mx-2 mb-1 flex items-center justify-between rounded-lg bg-white/[0.04] p-1" aria-label="Quick reactions">
          {['👍', '❤️', '😂', '🎉', '👀'].map((emoji) => (
            <button
              key={emoji}
              type="button"
              onClick={() => { onReact(messageId, emoji); onClose(); }}
              className="grid h-9 w-9 place-items-center rounded-lg text-base transition-colors hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-400"
              aria-label={`React with ${emoji}`}
            >
              {emoji}
            </button>
          ))}
        </div>
      )}

      {onReply && (
        <button
          type="button"
          role="menuitem"
          onClick={() => { onReply(messageId); onClose(); }}
          className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-white/10 text-white/90 transition-colors"
        >
          <Reply className="w-4 h-4" />
          <span className="text-sm font-medium">Reply</span>
        </button>
      )}

      <button 
        type="button"
        role="menuitem"
        onClick={() => { onCopy(content); onClose(); }}
        className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-white/10 text-white/90 transition-colors"
      >
        <Copy className="w-4 h-4" />
        <span className="text-sm font-medium">Copy Text</span>
      </button>
      
      <button 
        type="button"
        role="menuitem"
        onClick={() => { onShare(messageId); onClose(); }}
        className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-white/10 text-white/90 transition-colors"
      >
        <Share2 className="w-4 h-4" />
        <span className="text-sm font-medium">Share Message</span>
      </button>

      {isMe && onEdit && (
        <button 
          type="button"
          role="menuitem"
          onClick={() => { onEdit(messageId); onClose(); }}
          className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-white/10 text-white/90 transition-colors"
        >
          <Edit2 className="w-4 h-4" />
          <span className="text-sm font-medium">Edit Message</span>
        </button>
      )}

      {canManage && onPin && (
        <button
          type="button"
          role="menuitem"
          onClick={() => { onPin(messageId); onClose(); }}
          className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-white/10 text-white/90 transition-colors"
        >
          <Pin className="w-4 h-4" />
          <span className="text-sm font-medium">{isPinned ? 'Unpin Message' : 'Pin Message'}</span>
        </button>
      )}

      {canDelete && onDelete && (
        <>
          <div className="h-px bg-white/10 my-1 mx-2" />
          <button 
            type="button"
            role="menuitem"
            onClick={() => { onDelete(messageId); onClose(); }}
            className="w-full px-4 py-2 text-left flex items-center gap-3 hover:bg-red-500/20 text-red-400 transition-colors"
          >
            <Trash2 className="w-4 h-4" />
            <span className="text-sm font-medium">Delete Message</span>
          </button>
        </>
      )}
    </div>
  );
};
